<script setup>
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {charity,asset,path,fmt} from '../data'
import {session,openModal,logout} from '../session'
import Icon from '../components/Icon.vue'
import Coin from '../components/Coin.vue'
const route=useRoute(),category=ref('全部'),slide=ref(0),query=ref(''),activeTab=ref('排行榜'),filters=ref(false),coin=ref('USDT'),network=ref('ETH'),amount=ref(''),address=ref(''),hash=ref(''),receipt=ref(null),message=ref(''),selected=ref(null)
const section=computed(()=>route.params.section)
const banners=[['我們關懷每一位陷入戰爭災難的兒童','409d2b38d3103f4f.jpg'],['我們幫助消除飢餓','474d7ad6e890e265.jpg'],['我們讓計算機和以太網絡進入世界每個角落','924f557a9a47fa15.jpg'],['我們在災難中提供希望','bdb62b7ed08ba2ce.jpg'],['我們投資於偏遠地區國家的教育未來','d9bfaf5ec8022daa.jpg'],['我們讓殘障者重獲新生','d6c929ab13ae70e6.jpg']]
const quotes=[['ETH',1725.7971,1,1000],['USDC',1.0111413,1000,1e9],['BTC',61307.0101,.1,1000],['USDT',1.01,3000,1e8],['SOL',72.5786,100,5000]],filteredQuotes=computed(()=>quotes.filter(q=>category.value==='全部'||category.value===q[0]))
const titles={about:'關於 NewQuantCapital',privacy:'隱私權政策',content:'服務條款',agreement:'使用者協議','risk-disclosure':'風險揭露聲明','regulatory-information':'監管資訊','help-center':'幫助中心',profile:'個人資料',kyc:'身分驗證',messages:'公告列表'}
watch(()=>route.fullPath,()=>{category.value='全部';message.value='';selected.value=null;amount.value='';address.value='';hash.value='';receipt.value=null})
function receiptChange(event){const f=event.target.files?.[0];message.value='';if(f&&!['image/png','image/jpeg'].includes(f.type)){message.value='請選擇 PNG 或 JPEG 圖片';receipt.value=null;return}if(f?.size>10*1024*1024){message.value='圖片不可超過 10 MB';receipt.value=null;return}receipt.value=f?.name||null}
function submitFunds(){message.value='';if(!Number.isFinite(Number(amount.value))||Number(amount.value)<=0){message.value='請輸入有效金額';return}if(section.value==='deposit'&&!receipt.value){message.value='請選擇轉帳截圖';return}if(section.value==='withdraw'&&!address.value.trim()){message.value='請輸入演示地址';return}session.orders.push({name:section.value==='deposit'?'充值演示申請':'提現演示申請',amount:amount.value,symbol:coin.value});message.value='本地演示已完成。未傳送資料、未執行轉帳。';amount.value=''}
</script>
<template>
<template v-if="section==='charity'"><section class="charity-banner"><img :src="asset(banners[slide][1])" :alt="$tr(banners[slide][0])"/><h1>{{ $tr(banners[slide][0]) }}</h1><div class="carousel-dots"><button v-for="(b,i) in banners" :key="b[0]" :class="{active:slide===i}" :aria-label="$tr('公益輪播第 '+(i+1)+' 張：'+b[0])" :aria-pressed="slide===i" @click="slide=i"></button></div></section><section class="charity-intro"><h2 class="section-heading">{{ $tr("讓善意，抵達世界的每個角落") }}</h2><p>{{ $tr("以區塊鏈連接愛心，讓每一份支持化為真實的改變。一起為需要幫助的人們，帶來希望與機會。") }}</p></section><section class="container section-pad"><div class="section-row"><h2 class="section-heading">{{ $tr("公益項目") }}</h2><span class="muted">{{ $tr("用行動，讓世界更好") }}</span></div><div class="three-cols"><article v-for="(p,i) in charity" :key="p[0]" class="charity-card"><img :src="asset(p[1])" :alt="$tr(p[0])" loading="lazy"/><div><h3>{{ $tr(p[0]) }}</h3><div class="summary-line"><small>{{ $tr("已募集") }}</small><strong>{{ $tr(p[3]) }}{{ $tr(" USDT") }}</strong></div><div class="progress"><span :style="{width:p[2]+'%'}"></span></div><div class="summary-line"><small>{{ $tr("目標 ") }}{{ $tr(p[4]) }}{{ $tr(" USDT") }}</small><small>{{ $tr(p[2]) }}%</small></div><p class="mini-label" style="margin-top:12px">{{ $tr("受益人數 ") }}{{ $tr(p[5]) }}</p><button class="primary-button wide-button" @click="openModal('donate','支持公益項目',{name:p[0],symbol:'USDT',min:1})">{{ $tr("立即捐贈 →") }}</button></div></article></div></section><section class="container section-pad section-bordered"><div class="two-cols"><div><small class="mini-label">{{ $tr("累計善款") }}</small><p class="metric section-gap">70,777,391 <small>{{ $tr("USDT") }}</small></p></div><div><small class="mini-label">{{ $tr("累計受益人數") }}</small><p class="metric section-gap">1,314,922 <small>{{ $tr("人") }}</small></p></div></div><div class="card section-gap"><h2>{{ $tr("我的捐贈") }}</h2><p class="empty">{{ $tr("暫無捐贈記錄") }}</p><p class="mini-label">{{ $tr("以上為原站展示數據的靜態快照；本地捐贈僅作交互演示。") }}</p></div></section><section class="container section-pad section-bordered"><h2 class="section-heading">{{ $tr("我們如何運作") }}</h2><div class="four-cols section-gap"><div v-for="(s,i) in ['選擇公益項目','選擇捐贈金額','確認捐贈','追蹤公益進展']" :key="s"><p class="metric">0{{ $tr(i+1) }}</p><h3 style="margin-top:20px">{{ $tr(s) }}</h3></div></div></section></template>
<template v-else-if="section==='c2c'"><div class="page-wrap"><nav class="subnav"><RouterLink v-for="[label,id] in [['買入','buy'],['賣出','sell'],['我的訂單','orders'],['收款帳戶','accounts']]" :key="id" :to="path('/c2c/'+id)">{{ $tr(label) }}</RouterLink></nav><div class="summary-line"><div><h1 class="page-title">{{ $tr("C2C 交易") }}</h1><p class="page-desc">{{ $tr("法幣與加密資產場外撮合，平台託管結算") }}</p></div><button class="secondary-button" @click="openModal('info','申請商家',{description:'本地演示未連接商家審核服務。'})">{{ $tr("申請商家") }}</button></div><div v-if="['orders','accounts'].includes(route.params.id)" class="card section-gap"><h2>{{ $tr(route.params.id==='orders'?'我的訂單':'收款帳戶') }}</h2><div class="empty">{{ $tr("暫無") }}{{ $tr(route.params.id==='orders'?'訂單':'收款帳戶') }}</div><button v-if="route.params.id==='accounts'" class="primary-button" @click="openModal('info','新增收款帳戶',{description:'本地演示不收集銀行卡或真實收款帳戶資料。'})">{{ $tr("新增收款帳戶") }}</button></div><div v-else class="c2c-grid section-gap"><section class="card"><h2 style="font-size:1.25rem">{{ $tr("選擇報價") }}</h2><div class="filter-row"><button v-for="c in ['全部','ETH','USDC','BTC','USDT','SOL']" :class="{active:category===c}" @click="category=c">{{ $tr(c) }}</button><label>{{ $tr("法幣") }}<select><option :value="&quot;全部&quot;">{{ $tr("全部") }}</option><option :value="&quot;USD&quot;">{{ $tr("USD") }}</option></select></label></div><div class="two-cols"><button v-for="q in filteredQuotes" :key="q[0]" class="quote-card" :class="{selected:selected===q}" @click="selected=q"><span class="coin-label"><Coin :symbol="q[0]"/><strong>{{ $tr(q[0]) }}{{ $tr(" / USD") }}</strong></span><strong class="quote-price">{{ $tr(fmt(q[1])) }} <small>{{ $tr("USD") }}</small></strong><span class="mini-label">{{ $tr("限額 ") }}{{ $tr(fmt(q[2])) }}–{{ $tr(fmt(q[3])) }} {{ $tr(q[0]) }}</span><span class="tag-chip">{{ $tr("銀行轉帳") }}</span></button></div></section><aside class="card"><div v-if="!selected" class="empty"><Icon name="hand-coins"/>{{ $tr("請從左側選擇一個報價以繼續") }}</div><form v-else class="form-stack" @submit.prevent="openModal('c2c','確認 C2C '+(route.params.id==='sell'?'賣出':'買入'),{name:selected[0]+'/USD',symbol:selected[0],min:selected[2],max:selected[3],amount})"><h2>{{ $tr(route.params.id==='sell'?'賣出':'買入') }} {{ $tr(selected[0]) }}</h2><p class="metric">{{ $tr(fmt(selected[1])) }} <small>{{ $tr("USD") }}</small></p><label>{{ $tr("數量") }}<input v-model="amount" inputmode="decimal" :placeholder="$tr(&quot;請輸入數量&quot;)"/></label><div class="summary-line"><span class="muted">{{ $tr("支付金額") }}</span><strong>{{ $tr(fmt((Number(amount)||0)*selected[1])) }}{{ $tr(" USD") }}</strong></div><button class="primary-button">{{ $tr(route.params.id==='sell'?'賣出':'買入') }} {{ $tr(selected[0]) }}</button><p class="notice">{{ $tr("本地演示不產生真實訂單。") }}</p></form></aside></div></div></template>
<template v-else-if="section==='copytrade'"><div class="container copytrade"><p class="page-kicker">{{ $tr("跟隨專業交易員") }}</p><h1 class="page-title">{{ $tr("跟單交易") }}</h1><p class="page-desc">{{ $tr("發現、評估並跟隨經過驗證的交易員策略。透明績效、回測信號、完全自主的風險管理。") }}</p><div class="copy-filters"><div class="record-tabs"><button v-for="t in ['排行榜','我的跟隨','我的跟單']" :class="{active:activeTab===t}" @click="activeTab=t">{{ $tr(t) }}</button></div><input v-model="query" :placeholder="$tr(&quot;搜尋交易員&quot;)" :aria-label="$tr(&quot;搜尋交易員&quot;)"/><button class="secondary-button" :aria-expanded="filters" @click="filters=!filters">{{ $tr("篩選") }}</button></div><div v-if="filters" class="filter-row"><label>{{ $tr("風險等級") }}<select><option :value="&quot;全部&quot;">{{ $tr("全部") }}</option><option :value="&quot;低風險&quot;">{{ $tr("低風險") }}</option><option :value="&quot;中風險&quot;">{{ $tr("中風險") }}</option><option :value="&quot;高風險&quot;">{{ $tr("高風險") }}</option></select></label><label>{{ $tr("排序") }}<select><option :value="&quot;收益率&quot;">{{ $tr("收益率") }}</option><option :value="&quot;跟隨人數&quot;">{{ $tr("跟隨人數") }}</option><option :value="&quot;交易天數&quot;">{{ $tr("交易天數") }}</option></select></label></div><div class="empty">{{ $tr(query?'沒有符合的交易員':activeTab==='排行榜'?'目前沒有可展示的交易員':activeTab==='我的跟隨'?'暫無跟隨':'暫無跟單') }}<p>{{ $tr("所有績效數據每日更新並經過驗證。") }}</p></div></div></template>
<template v-else-if="['deposit','withdraw'].includes(section)"><div class="container section-pad"><div class="summary-line"><RouterLink class="muted" :to="path('/assets')">{{ $tr("← 返回") }}</RouterLink><RouterLink class="muted" :to="path('/assets/records')">{{ $tr("歷史記錄") }}</RouterLink></div><h1 class="page-title">{{ $tr(section==='deposit'?'充值':'提現') }}</h1><p class="page-desc">{{ $tr(section==='deposit'?'選擇幣種與網路，向以下地址轉帳完成充值':'選擇幣種與網路，輸入提現地址及金額') }}</p><form class="form-stack section-gap" @submit.prevent="submitFunds"><label>{{ $tr("選擇幣種") }}<select v-model="coin"><option :value="&quot;USDT&quot;">{{ $tr("USDT") }}</option><option :value="&quot;USDC&quot;">{{ $tr("USDC") }}</option><option :value="&quot;BTC&quot;">{{ $tr("BTC") }}</option><option :value="&quot;ETH&quot;">{{ $tr("ETH") }}</option></select></label><label>{{ $tr("選擇網路") }}<select v-model="network"><option :value="&quot;ETH&quot;">{{ $tr("ETH") }}</option><option :value="&quot;TRON&quot;">{{ $tr("TRON") }}</option><option :value="&quot;BTC&quot;">{{ $tr("BTC") }}</option></select></label><div class="two-cols"><div class="form-stack"><p class="notice">{{ $tr("本地演示，請勿向任何演示地址轉帳，也無需上傳真實交易憑證。") }}</p><template v-if="section==='deposit'"><label>{{ $tr("充值地址") }}<code class="card" style="overflow-wrap:anywhere">{{ $tr("DEMO-ADDRESS-NOT-FOR-TRANSFER") }}</code></label></template><label v-else>{{ $tr("提現地址") }}<input v-model="address" :placeholder="$tr(&quot;請輸入演示地址&quot;)"/></label><label>{{ $tr("轉帳金額") }}<input v-model="amount" inputmode="decimal" :placeholder="$tr(&quot;請輸入金額&quot;)"/></label><label v-if="section==='deposit'">{{ $tr("交易哈希（TXID）") }}<input v-model="hash" :placeholder="$tr(&quot;（選填）請貼上演示交易哈希&quot;)"/></label></div><label v-if="section==='deposit'" class="upload-area">{{ $tr("轉帳截圖") }}<span class="card">{{ $tr(receipt||'點擊選擇本地演示圖片（PNG / JPEG）') }}<input type="file" accept="image/png,image/jpeg" @change="receiptChange"/><small>{{ $tr("僅在本機選擇，不上傳檔案") }}</small></span></label></div><p v-if="message" role="status" class="notice">{{ $tr(message) }}</p><button class="primary-button">{{ $tr("提交演示") }}</button></form></div></template>
<template v-else><div class="container section-pad"><h1 class="page-title">{{section==='messages'?$tr('公告列表'):$t('common.notFound.title')}}</h1><div v-if="section==='messages'" class="card empty"><Icon name="mail"/>{{$tr('暫無公告')}}</div><RouterLink v-else class="green-link" :to="path('/')">{{$t('news.backToHome')}}</RouterLink></div></template>
</template>
<style scoped>.legal-page{max-width:960px;padding:64px 24px;margin:auto;line-height:1.85}.legal-page h1{font-size:2.25rem;margin-bottom:32px}.legal-page h2,.legal-page h3{margin:32px 0 16px}.legal-page p{color:#fff9;margin:16px 0;white-space:pre-line;overflow-wrap:anywhere}.news-detail>img{width:100%;border-radius:24px;margin:32px 0}.news-detail h1{font-size:2.5rem;line-height:1.4}.c2c-grid{display:grid;grid-template-columns:2fr 1fr;gap:24px}.quote-card{display:grid;gap:20px;text-align:left;background:#ffffff04;border:1px solid #ffffff0b;border-radius:20px;padding:24px}.quote-card.selected{border-color:var(--nt-accent);background:#a5ff4a06}.quote-price{font-size:1.625rem}.quote-price small{font-size:0.75rem;color:#fff8}.quote-card .tag-chip{width:max-content}.copytrade{max-width:1280px;padding:60px 32px;background:radial-gradient(ellipse at top,#a5ff4a08,transparent 60%)}.copy-filters{display:flex;align-items:center;gap:12px;margin-top:32px;border-bottom:1px solid #ffffff0b}.copy-filters .record-tabs{border:0;flex:1;padding-left:0}.copy-filters input{max-width:240px}.upload-area>span{min-height:270px;display:grid;align-content:center;gap:24px;text-align:center;border-style:dashed;background:#0c1017}.upload-area small{color:#fff6}.upload-area input{width:100%}.profile-settings{margin:40px 0}.profile-settings>div{padding:20px 0;border-top:1px solid #ffffff0a}.carousel-dots button{box-sizing:content-box;border:8px solid transparent;background-clip:padding-box}.charity-banner{background:#16191a}@media(max-width:900px){.c2c-grid{grid-template-columns:1fr}.copy-filters{flex-wrap:wrap;padding-bottom:16px}.copy-filters .record-tabs{flex-basis:100%}.copy-filters input{max-width:none;flex:1;min-width:0}}@media(max-width:600px){.news-detail h1{font-size:1.625rem}.copytrade{padding:40px 20px}.charity-banner h1{line-height:1.5}.c2c-grid .two-cols{grid-template-columns:1fr}.quote-price{font-size:1.5rem}.carousel-dots{gap:0}.upload-area>span{min-height:180px}}
